import { type AudioPlayer, createAudioPlayer, setAudioModeAsync } from 'expo-audio';

import { usePrefs } from '@/state/prefs';

// Generated by scripts/make-sounds.mjs.
const SOURCES = {
  join: require('../../assets/sounds/join.wav'),
  turn: require('../../assets/sounds/turn.wav'),
  tick: require('../../assets/sounds/tick.wav'),
  lock: require('../../assets/sounds/lock.wav'),
  pop: require('../../assets/sounds/pop.wav'),
  drumroll: require('../../assets/sounds/drumroll.wav'),
  win: require('../../assets/sounds/win.wav'),
  lose: require('../../assets/sounds/lose.wav'),
};

export type Sound = keyof typeof SOURCES;

const players = new Map<Sound, AudioPlayer>();
let configured = false;

function player(sound: Sound): AudioPlayer {
  if (!configured) {
    configured = true;
    // Short effects mix with the user's music instead of stopping it, and respect the silent switch.
    setAudioModeAsync({ playsInSilentMode: false, interruptionMode: 'mixWithOthers' }).catch(() => {});
  }
  let p = players.get(sound);
  if (!p) {
    p = createAudioPlayer(SOURCES[sound]);
    players.set(sound, p);
  }
  return p;
}

/** Plays [sound] from the start, unless the player muted the app. */
export function play(sound: Sound) {
  if (usePrefs.getState().muted) return;
  try {
    const p = player(sound);
    p.seekTo(0)
      .then(() => p.play())
      .catch(() => {});
  } catch {
    // A sound is never worth crashing a game over.
  }
}

export function stop(sound: Sound) {
  players.get(sound)?.pause();
}
